using System;
using System.Data;
using System.Text;
using DNAide.Data;
using DNAide.Web;
using Sunplus.Accounting.DataAccess.IBCDLL.Accounting;

public partial class AllCustomerTurnOver : PageBase
{
    protected void Page_Load(object sender, EventArgs e)
    {
        custTurnOverHeaderStr.Text = Resources.Language.AllCustomerTurnOver;
        custTurnOverContentHtml.Text = GenCustTurnOver();
    }

    private string GenCustTurnOver()
    {
        StringBuilder html = new StringBuilder();
        DateTime fDate = Convert.ToDateTime(Request["fdate"]);
        DateTime tDate = Convert.ToDateTime(Request["tdate"]);
        html.Append(Sunplus.Accounting.Core.Web.WebUtils.LoadHtml("TurnOver/AllCustTurnOverHeader.htm", new string[] { "{no}", "{user}", "{turnover}", "{fdate}", "{tdate}" }, new string[] { Resources.Language.No, Resources.Language.User, Resources.Language.TurnOver, fDate.ToShortDateString(), tDate.ToShortDateString() }));
        string content = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("TurnOver/AllCustTurnOverRow.htm");
        try
        {
            DbResult ds = null;
            if (Request["fdate"] == null || Request["tdate"] == null) return "";
            ds = CustomerTurnOver.RptCustomerTurnOver(fDate, tDate);
            string row = "";
            if (ds != null)
            {
                DataTable tbl = ds.ResultSet.Tables[0];
                int num = 0;
                string odd_even = "";
                for (int i = 0; i < tbl.Rows.Count; i++)
                {
                    num = i + 1;
                    row = content;
                    odd_even = (odd_even == "") ? "evenrow" : "";
                    string strUsername = tbl.Rows[i]["username"] as string ?? string.Empty;
                    TemplateHandler.Assign(ref row, "{odd_even}", odd_even);
                    TemplateHandler.Assign(ref row, "{no}", num.ToString());
                    TemplateHandler.Assign(ref row, "{user}", strUsername);
                    TemplateHandler.Assign(ref row, "{turnover}", IBCUtils.FormatHandler.FormatNumber20(tbl.Rows[i]["turnover"]));
                    html.Append(row);
                }
            }
        }
        catch (Exception ex)
        {
            Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
        }
        html.Append("</table>");
        return html.ToString();
    }
}